    //Driver Code Starts
#include <iostream>
#include<vector>
using namespace std;

//Driver Code Ends

int cntPairs(vector<int>&arr, int k) {
    int n=arr.size();
    int cnt = 0;

    // Loop through all possible pairs of elements in the array
    for (int i = 0; i < n; i++) {
        for (int j = i+1; j < n; j++) {

            // Check if bitwise XOR of the pair is less than K
            if ((arr[i] ^ arr[j]) < k) {
                cnt++;
            }
        }
    }

    // return all pairs less than k
    return cnt;
}

